/* donate.js —— 全站通用打赏按钮（支付宝个人收款码）
   用法：在页面 </body> 前加一行
     <script src="https://lisazhang7711.github.io/donate/donate.js" defer></script>
   特点：Shadow DOM 样式隔离；二维码 base64 内嵌，无外部图片请求；
        任何脚本加载失败都只影响按钮本身，不影响站点功能。 */
(function () {
  'use strict';
  if (window.__ZY_DONATE__) return;
  window.__ZY_DONATE__ = true;

  var PAY_URL = "https://qr.alipay.com/fkx13207dsvcc1ylk0pd053";
  var QR_DATA = "data:image/jpeg;base64,";

  var host = document.createElement('div');
  /* 位置优先级：window.DONATE_POS 显式指定 > 自动探测 #fb-btn（反馈键）叠到其上方 > 默认右下角。
     反馈键在多数站点位于 right:16/bottom:16，直接同位会重叠——探测到就往上挪。 */
  var P = window.DONATE_POS || {};
  function place(force) {
    var right = P.right, bottom = P.bottom;
    if (bottom == null) {
      var fb = document.getElementById('fb-btn');
      if (fb && fb.getBoundingClientRect) {
        var rc = fb.getBoundingClientRect();
        if (rc.height) {
          if (right == null) right = 16;
          bottom = Math.ceil(window.innerHeight - rc.top) + 10;
        }
      }
      if (bottom == null && !force && document.readyState !== 'complete') {
        /* 反馈键若是动态注入的，等 load 再算一次 */
        window.addEventListener('load', function () { place(true); });
        return;
      }
    }
    if (right == null) right = 14;
    if (bottom == null) bottom = 14;
    host.style.cssText = 'all:initial;position:fixed;z-index:2147483000;right:' + right +
      'px;bottom:' + bottom + 'px;';
  }
  place();
  var root = host.attachShadow ? host.attachShadow({mode:'open'}) : host;

  var css = [
    '.dbtn{display:flex;align-items:center;gap:6px;border:0;cursor:pointer;',
    '  background:#1677ff;color:#fff;font:13px/1 -apple-system,"PingFang SC","Microsoft YaHei",sans-serif;',
    '  padding:9px 14px;border-radius:20px;box-shadow:0 2px 8px rgba(0,0,0,.25);}',
    '.dbtn:hover{background:#0958d9}',
    '.dbtn svg{width:14px;height:14px;fill:currentColor}',
    '.dm{position:fixed;inset:0;background:rgba(0,0,0,.45);display:flex;',
    '  align-items:center;justify-content:center;padding:16px}',
    '.card{background:#fff;border-radius:14px;max-width:300px;width:100%;padding:20px;',
    '  font:14px/1.6 -apple-system,"PingFang SC","Microsoft YaHei",sans-serif;color:#333;',
    '  text-align:center;position:relative}',
    '.card h3{margin:0 0 4px;font-size:16px}',
    '.card p{margin:4px 0;font-size:12px;color:#888}',
    '.card img{width:220px;height:220px;display:block;margin:10px auto 4px;border-radius:8px;}',
    '.card a{color:#1677ff;text-decoration:none;font-size:13px}',
    '.x{position:absolute;top:8px;right:12px;border:0;background:none;font-size:18px;',
    '  color:#aaa;cursor:pointer;line-height:1}',
    '.x:hover{color:#555}',
    '@media (max-width:600px){.dbtn{padding:8px 11px;font-size:12px}}'
  ].join('');

  var svg = '<svg viewBox="0 0 24 24"><path d="M12 21s-7.5-4.6-10-9.3C.6 8.6 2.3 5 5.7 5c2 0 3.4 1.1 4.3 2.7h4c.9-1.6 2.3-2.7 4.3-2.7 3.4 0 5.1 3.6 3.7 6.7C19.5 16.4 12 21 12 21z"/></svg>';

  function open() {
    var m = document.createElement('div');
    m.className = 'dm';
    m.innerHTML =
      '<div class="card">' +
      '<button class="x" aria-label="关闭">\u00d7</button>' +
      '<h3>感谢支持</h3>' +
      '<p>支付宝扫一扫 · 金额随意</p>' +
      '<img alt="支付宝收款码" src="' + QR_DATA + '">' +
      '<p><a href="' + PAY_URL + '" target="_blank" rel="noopener">在手机上看？点这里直接打开支付宝</a></p>' +
      '<p>本站由个人维护，打赏用于服务器与内容成本</p>' +
      '</div>';
    m.addEventListener('click', function (e) {
      if (e.target === m || e.target.className === 'x') close();
    });
    function close() { m.remove(); document.removeEventListener('keydown', onKey); }
    function onKey(e) { if (e.key === 'Escape') close(); }
    document.addEventListener('keydown', onKey);
    root.appendChild(m);
  }

  var btn = document.createElement('button');
  btn.className = 'dbtn';
  btn.setAttribute('aria-label', '打赏');
  btn.innerHTML = svg + '<span>打赏</span>';
  btn.addEventListener('click', open);

  var style = document.createElement('style');
  style.textContent = css;
  root.appendChild(style);
  root.appendChild(btn);
  (document.body || document.documentElement).appendChild(host);
})();
